import { useState, useCallback, useEffect } from 'react';

/**
 * 🎯 Hook réutilisable pour persister le filtre actif des widgets
 * Utilise un objet consolidé dans localStorage pour optimiser la performance
 *
 * Usage:
 * const [filter, setFilter] = useWidgetFilter('inspection-widget', 'waiting_image');
 *
 * @param {string} widgetKey - Clé unique pour le widget (ex: 'inspection-widget', 'project-widget', 'task-widget')
 * @param {string} defaultValue - Valeur par défaut si rien en localStorage
 * @returns {[string, (value: string) => void]} [filter, setFilter]
 */

const STORAGE_KEY = 'widget-filters';
const STORAGE_EVENT = 'widget-filters-updated';

export const useWidgetFilter = (widgetKey, defaultValue = '') => {
  const getInitialFilter = () => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return defaultValue;
      const filters = JSON.parse(stored);
      return filters[widgetKey] ?? defaultValue;
    } catch {
      return defaultValue;
    }
  };

  const [filter, setFilter] = useState(getInitialFilter);

  useEffect(() => {
    const handleCustomEvent = (event) => {
      if (event?.detail?.widgetKey === widgetKey) {
        setFilter(event.detail.value ?? defaultValue);
      }
    };

    const handleStorageEvent = (event) => {
      if (event.key === STORAGE_KEY) {
        setFilter(getInitialFilter());
      }
    };

    window.addEventListener(STORAGE_EVENT, handleCustomEvent);
    window.addEventListener('storage', handleStorageEvent);

    return () => {
      window.removeEventListener(STORAGE_EVENT, handleCustomEvent);
      window.removeEventListener('storage', handleStorageEvent);
    };
  }, [widgetKey, defaultValue]);

  const updateFilter = useCallback((value) => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      const filters = stored ? JSON.parse(stored) : {};
      filters[widgetKey] = value;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(filters));
      setFilter(value);

      window.dispatchEvent(new CustomEvent(STORAGE_EVENT, {
        detail: { widgetKey, value },
      }));
    } catch {
      setFilter(value);
    }
  }, [widgetKey]);

  return [filter, updateFilter];
};

export default useWidgetFilter;

