/**
 * 🏗️ StorageManager — singleton central pour tout accès localStorage
 *
 * Rôle :
 * - Wrappe TOUTES les opérations localStorage (get/set/remove/clear)
 * - Registry de clés avec category, defaultValue, ttl optionnel
 * - clearCategory(cat) pour le cleanup logout (remplace le regex)
 * - try/catch systématique + QuotaExceededError
 */

const CATEGORIES = {
  AUTH: 'auth',
  UI: 'ui',
  BUSINESS: 'business',
  CACHE: 'cache',
};

const _registry = new Map();

function _try(fn, fallback = undefined) {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

const StorageManager = {
  CATEGORIES,

  /**
   * Déclarer une clé dans le registry (optionnel, pour clearCategory)
   */
  register(key, { category = CATEGORIES.UI, defaultValue = undefined, ttl = null } = {}) {
    _registry.set(key, { category, defaultValue, ttl });
  },

  /**
   * Lire une valeur
   */
  get(key) {
    return _try(() => {
      const raw = localStorage.getItem(key);
      if (raw === null) return undefined;
      const entry = _registry.get(key);
      if (entry?.ttl) {
        const parsed = JSON.parse(raw);
        if (parsed._ts && Date.now() - parsed._ts > entry.ttl) {
          localStorage.removeItem(key);
          return entry.defaultValue;
        }
        return parsed.value;
      }
      return JSON.parse(raw);
    }, _registry.get(key)?.defaultValue);
  },

  /**
   * Écrire une valeur
   */
  set(key, value) {
    return _try(() => {
      const entry = _registry.get(key);
      if (entry?.ttl) {
        localStorage.setItem(key, JSON.stringify({ value, _ts: Date.now() }));
      } else {
        localStorage.setItem(key, JSON.stringify(value));
      }
      return true;
    }, false);
  },

  /**
   * Supprimer une clé
   */
  remove(key) {
    _try(() => localStorage.removeItem(key));
  },

  /**
   * Supprimer toutes les clés d'une catégorie
   */
  clearCategory(category) {
    const keysToRemove = [];
    for (const [key, entry] of _registry) {
      if (entry.category === category) keysToRemove.push(key);
    }
    // Fallback : clés non registrées mais matchant le pattern legacy
    const LEGACY_PATTERNS = {
      [CATEGORIES.AUTH]: /^auth|token|user|remembered|debug|geo|email.*modal$/i,
      [CATEGORIES.UI]: /^theme|sidebar|filter|view|notification|column|table_sort/i,
      [CATEGORIES.CACHE]: /^.*_cache$/,
    };
    if (LEGACY_PATTERNS[category]) {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && LEGACY_PATTERNS[category].test(k)) keysToRemove.push(k);
      }
    }
    const unique = [...new Set(keysToRemove)];
    unique.forEach((k) => _try(() => localStorage.removeItem(k)));
    return unique.length;
  },

  /**
   * Vider tout le localStorage
   */
  clearAll() {
    _try(() => localStorage.clear());
  },

  /**
   * Lister toutes les clés registrées (debug)
   */
  getRegisteredKeys() {
    return Object.fromEntries(_registry);
  },
};

// ── Enregistrement des clés centralisées ──────────────────────────────────
