StorageManager.register('rememberedEmail',    { category: CATEGORIES.AUTH });
StorageManager.register('theme',              { category: CATEGORIES.UI, defaultValue: 'system' });
StorageManager.register('sidebarCollapsed',   { category: CATEGORIES.UI, defaultValue: false });
StorageManager.register('sidebar_preferences_v1', { category: CATEGORIES.UI });
StorageManager.register('table_sorting',      { category: CATEGORIES.UI });
StorageManager.register('userProfile_cache',  { category: CATEGORIES.CACHE, defaultValue: null, ttl: 86400000 });

export default StorageManager;

